css:
.cafe-sim-container {
    padding: 28px;
    background: linear-gradient(170deg, #FBF7F0 0%, #F0E6D3 40%, #E8DCCA 100%);
    min-height: 100vh;
    font-family: -apple-system, 'Segoe UI', Roboto, Helvetica, sans-serif;
    color: #3E2723;
}

.cafe-sim-header {
    background: linear-gradient(135deg, #3E2723 0%, #4E342E 40%, #5D4037 100%);
    color: #EFEBE9;
    border-radius: 20px;
    padding: 36px 32px 32px;
    text-align: center;
    margin-bottom: 28px;
    box-shadow: 0 12px 32px rgba(62,39,35,0.35);
    position: relative;
    overflow: hidden;
}

.cafe-sim-header::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    height: 5px;
    background: linear-gradient(90deg, #1B5E20, #2E7D32, #4CAF50, #81C784, #2E7D32);
}

.cafe-sim-header::after {
    content: '';
    position: absolute;
    bottom: -60px;
    right: -40px;
    width: 180px;
    height: 180px;
    border-radius: 50%;
    background: rgba(255,255,255,0.03);
}

.cafe-sim-header-badge {
    display: inline-block;
    background: rgba(255,255,255,0.1);
    border: 1px solid rgba(255,255,255,0.15);
    border-radius: 20px;
    padding: 4px 16px;
    font-size: 0.8rem;
    letter-spacing: 0.06em;
    margin-bottom: 12px;
    color: #D7CCC8;
}

.cafe-sim-header h1 {
    font-family: Georgia, 'Times New Roman', serif;
    font-size: 2rem;
    margin: 0 0 8px 0;
    color: #FFF8E1;
    letter-spacing: 0.02em;
}

.cafe-sim-header p {
    font-size: 0.92rem;
    color: #BCAAA4;
    margin: 0;
    max-width: 500px;
    margin-left: auto;
    margin-right: auto;
}

.cafe-sim-period-counter {
    text-align: center;
    font-size: 1.05rem;
    color: #5D4037;
    margin-bottom: 24px;
    font-weight: 600;
    letter-spacing: 0.02em;
}

.cafe-sim-period-counter span {
    margin: 0 3px;
}

.cafe-sim-kpi-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 16px;
    margin-bottom: 28px;
}

.cafe-sim-kpi-card {
    background: #FFFFFF;
    border-radius: 14px;
    padding: 22px 16px 18px;
    text-align: center;
    border-top: 4px solid #8D6E63;
    box-shadow: 0 4px 16px rgba(62,39,35,0.08);
    transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.cafe-sim-kpi-card:hover {
    transform: translateY(-3px);
    box-shadow: 0 8px 24px rgba(62,39,35,0.14);
}

.cafe-sim-kpi-card.cafe-sim-kpi-debt {
    border-top-color: #C62828;
}

.cafe-sim-kpi-card.cafe-sim-kpi-quality {
    border-top-color: #2E7D32;
}

.cafe-sim-kpi-card.cafe-sim-kpi-reputation {
    border-top-color: #FF8F00;
}

.cafe-sim-kpi-icon {
    font-size: 1.4rem;
    margin-bottom: 6px;
}

.cafe-sim-kpi-label {
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: #8D6E63;
    margin-bottom: 8px;
    font-weight: 700;
}

.cafe-sim-kpi-value {
    font-size: 1.7rem;
    font-weight: 700;
    color: #3E2723;
    font-family: Georgia, 'Times New Roman', serif;
}

.cafe-sim-briefing {
    background: #FFFFFF;
    border-radius: 14px;
    margin-bottom: 24px;
    border-left: 5px solid #FF8F00;
    box-shadow: 0 4px 16px rgba(62,39,35,0.08);
    overflow: hidden;
}

.cafe-sim-briefing-header {
    background: linear-gradient(135deg, #FFF8E1, #FFF3E0);
    padding: 16px 24px;
    border-bottom: 1px solid #FFE0B2;
}

.cafe-sim-briefing-header h3 {
    font-family: Georgia, serif;
    font-size: 1.05rem;
    color: #E65100;
    margin: 0;
}

.cafe-sim-briefing-body {
    padding: 20px 24px;
    font-size: 0.92rem;
    line-height: 1.7;
    color: #4E342E;
}

.cafe-sim-controls {
    background: #FFFFFF;
    border-radius: 14px;
    padding: 28px;
    margin-bottom: 24px;
    border-top: 4px solid #2E7D32;
    box-shadow: 0 4px 16px rgba(62,39,35,0.08);
}

.cafe-sim-controls h3 {
    font-family: Georgia, serif;
    font-size: 1.1rem;
    color: #1B5E20;
    margin: 0 0 22px 0;
    padding-bottom: 12px;
    border-bottom: 1px solid #E8F5E9;
}

.cafe-sim-input-group {
    margin-bottom: 20px;
}

.cafe-sim-input-group label {
    display: block;
    font-size: 0.85rem;
    font-weight: 700;
    color: #5D4037;
    margin-bottom: 8px;
    letter-spacing: 0.01em;
}

.cafe-sim-input-group select {
    width: 100%;
    padding: 11px 16px;
    border: 2px solid #D7CCC8;
    border-radius: 10px;
    background: #FAFAF7;
    color: #3E2723;
    font-size: 0.9rem;
    font-family: inherit;
    transition: border-color 0.2s ease, box-shadow 0.2s ease;
    cursor: pointer;
}

.cafe-sim-input-group select:focus {
    outline: none;
    border-color: #2E7D32;
    box-shadow: 0 0 0 3px rgba(46,125,50,0.12);
}

.cafe-sim-input-group select:hover {
    border-color: #8D6E63;
}

.cafe-sim-btn-row {
    margin-top: 24px;
    display: flex;
    align-items: center;
    gap: 12px;
}

.cafe-sim-submit-btn {
    background: linear-gradient(135deg, #2E7D32, #388E3C) !important;
    border: none !important;
    color: #FFFFFF !important;
    padding: 13px 36px !important;
    border-radius: 10px !important;
    font-size: 1rem !important;
    font-weight: 700 !important;
    cursor: pointer;
    transition: all 0.2s ease !important;
    letter-spacing: 0.02em;
    box-shadow: 0 4px 12px rgba(46,125,50,0.25);
}

.cafe-sim-submit-btn:hover {
    background: linear-gradient(135deg, #1B5E20, #2E7D32) !important;
    transform: translateY(-1px);
    box-shadow: 0 6px 16px rgba(46,125,50,0.35) !important;
}

.cafe-sim-undo-btn {
    border-color: #8D6E63 !important;
    color: #8D6E63 !important;
    border-radius: 10px !important;
    padding: 8px 18px !important;
    font-weight: 600 !important;
    transition: all 0.2s ease !important;
}

.cafe-sim-undo-btn:hover {
    background: #8D6E63 !important;
    color: #FFFFFF !important;
}

.cafe-sim-chart-section {
    background: #FFFFFF;
    border-radius: 14px;
    padding: 24px;
    margin-bottom: 24px;
    box-shadow: 0 4px 16px rgba(62,39,35,0.08);
}

.cafe-sim-chart-section h3 {
    font-family: Georgia, serif;
    font-size: 1rem;
    color: #5D4037;
    margin: 0 0 16px 0;
}

.cafe-sim-chart-wrapper {
    height: 280px;
    position: relative;
}

.cafe-sim-history {
    background: #FFFFFF;
    border-radius: 14px;
    padding: 24px;
    box-shadow: 0 4px 16px rgba(62,39,35,0.08);
    overflow-x: auto;
}

.cafe-sim-container .table {
    color: #3E2723;
    margin-bottom: 0;
}

.cafe-sim-container .table thead th {
    background: #EFEBE9;
    color: #5D4037;
    font-size: 0.75rem;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    border-bottom: 2px solid #D7CCC8;
    padding: 12px 10px;
    font-weight: 700;
}

.cafe-sim-container .table tbody td {
    border-color: #F5F0EB;
    font-size: 0.88rem;
    padding: 10px;
    vertical-align: middle;
}

.cafe-sim-container .table tbody tr:hover {
    background: #FFF8E1;
}

@media (max-width: 768px) {
    .cafe-sim-container {
        padding: 16px;
    }
    .cafe-sim-kpi-grid {
        grid-template-columns: repeat(2, 1fr);
        gap: 12px;
    }
    .cafe-sim-header {
        padding: 24px 20px;
        border-radius: 14px;
    }
    .cafe-sim-header h1 {
        font-size: 1.5rem;
    }
    .cafe-sim-kpi-value {
        font-size: 1.3rem;
    }
    .cafe-sim-controls {
        padding: 20px;
    }
    .cafe-sim-briefing-body {
        padding: 16px 20px;
    }
    .cafe-sim-btn-row {
        flex-direction: column;
        align-items: stretch;
    }
    .cafe-sim-submit-btn {
        width: 100%;
        text-align: center;
    }
}

