        _updateBriefing(state) {
            var period = state.currentPeriod || 1;
            var idx = Math.min(period - 1, 3);

            var briefEl = document.getElementById('briefingText');
            if (briefEl && window.mySimulation) {
                var keys = ['briefing_r1', 'briefing_r2', 'briefing_r3', 'briefing_r4'];
                briefEl.innerHTML = window.mySimulation.t(keys[idx]);
            }

            var panels = ['round1Decisions', 'round2Decisions', 'round3Decisions', 'round4Decisions'];
            for (var i = 0; i < panels.length; i++) {
                var panel = document.getElementById(panels[i]);
                if (panel) {
                    panel.style.display = (i === idx) ? 'block' : 'none';
                }
            }
        }
    }

    document.addEventListener('DOMContentLoaded', function() {
        window.mySimulation = new USF.SimulationFramework();
        window.mySimulation.initialize(new CafeEspecialidadAdapter(), {
            simulationType: 'cafe_especialidad_473',
            maxPeriods: 4,
            autoSaveInterval: 30000
        });
    });

})();
